"""Fragment shader BODIES for stage mode (figures crossing between windows).
No helpers or #version here — glsl_common.assemble() prepends the prelude.

silhouette: procedural walking figure against a LIT window pane.
sprite:     pre-rendered walk cycle from an atlas, against a lit pane.
ghost:      translucent hooded spectre with depth (uDepth) and turn (uYaw).
mansion:    the ballroom - SLOTS Victorian ghosts waltzing at depth.
spirits:    SLOTS faceless spirit lights in true 3D; trails follow a
            history of NH past positions.
SLOTS and NH are #defines injected by the renderer, never hard-coded here.
"""

SILHOUETTE_FRAG = "uniform vec2  iResolution;\nuniform float iTime;\nuniform float uLocal;     // figure position across THIS window, 0..1 (may be <0 or >1)\nuniform float uFacing;    // -1 left, +1 right\nuniform float uPhase;     // walk cycle 0..1\nuniform float uLit;       // window glow level\nuniform float uCrouch;    // posture 0..1\nuniform float uFigScale;  // figure height as a fraction of the window\nuniform float uMirror;\nout vec4 fragColor;\n// capsule distance\n// humanoid silhouette in figure space: feet at y=0, head near y=1\nfloat figure(vec2 p, float phase, float crouch){\n    float s = sin(phase*6.2831), c = cos(phase*6.2831);\n    float hip = 0.46 - 0.05*crouch;\n    float sh  = 0.80 - 0.07*crouch;\n\n    // legs swing opposite each other\n    vec2 hipL = vec2(-0.035, hip), hipR = vec2(0.035, hip);\n    vec2 kneeL = hipL + vec2( 0.085*s, -0.22);\n    vec2 kneeR = hipR + vec2(-0.085*s, -0.22);\n    vec2 footL = kneeL + vec2( 0.075*s, -0.24 + 0.05*max(s,0.0));\n    vec2 footR = kneeR + vec2(-0.075*s, -0.24 + 0.05*max(-s,0.0));\n    float d = sdCap(p, hipL, kneeL, 0.042);\n    d = min(d, sdCap(p, kneeL, footL, 0.034));\n    d = min(d, sdCap(p, hipR, kneeR, 0.042));\n    d = min(d, sdCap(p, kneeR, footR, 0.034));\n\n    // torso + head\n    d = min(d, sdCap(p, vec2(0.0,hip), vec2(0.0,sh), 0.085));\n    d = min(d, length(p - vec2(0.012*c, sh+0.115)) - 0.072);\n    // shoulders\n    d = min(d, sdCap(p, vec2(-0.075,sh), vec2(0.075,sh), 0.035));\n\n    // arms swing opposite the legs\n    vec2 shL = vec2(-0.08, sh-0.01), shR = vec2(0.08, sh-0.01);\n    vec2 elbL = shL + vec2(-0.055*s*0.8, -0.19);\n    vec2 elbR = shR + vec2( 0.055*s*0.8, -0.19);\n    d = min(d, sdCap(p, shL, elbL, 0.033));\n    d = min(d, sdCap(p, elbL, elbL + vec2(-0.045*s, -0.17), 0.026));\n    d = min(d, sdCap(p, shR, elbR, 0.033));\n    d = min(d, sdCap(p, elbR, elbR + vec2( 0.045*s, -0.17), 0.026));\n    return d;\n}\n\nvoid main(){\n    vec2 uv = gl_FragCoord.xy / iResolution;      // 0..1, y up\n    float xs = (uMirror>0.5) ? -1.0 : 1.0;\n\n    // ---- the lit window pane: warm glow, brighter in the middle, soft edges\n    vec2 c = uv - 0.5;\n    float pane = smoothstep(0.52,0.40, abs(c.x)) * smoothstep(0.52,0.40, abs(c.y));\n    float falloff = 1.0 - 0.55*length(c*vec2(1.0,1.25));\n    float grime = 0.86 + 0.14*fbm(uv*vec2(6.0,8.0));\n    vec3 warm = vec3(1.00,0.72,0.34);\n    float flicker = uLit * (0.97 + 0.03*sin(iTime*3.1));\n    vec3 col = warm * pane * falloff * grime * flicker * 0.55;\n\n    // faint curtain-ish vertical banding so the pane isn't a flat wash\n    col *= 0.92 + 0.08*sin(uv.x*38.0);\n\n    // ---- the figure occludes the glow\n    float h = max(0.15, uFigScale);\n    float aspect = iResolution.x / max(iResolution.y, 1.0);\n    // x must be aspect-scaled or the figure comes out squat and wide\n    vec2 fp = vec2((uv.x - uLocal) * aspect * xs * uFacing, (uv.y - 0.055)) / h;\n    float d = figure(fp, uPhase, uCrouch);\n    float body = smoothstep(0.012, -0.004, d);        // 1 inside the figure\n    // soft contact shadow under the feet\n    float sh = smoothstep(0.16,0.0, length((uv - vec2(uLocal, 0.050))/vec2(0.085,0.028)));\n    col *= 1.0 - 0.45*sh*pane;\n    col *= 1.0 - 0.97*body;\n\n    // thin rim of light leaking around the body sells the backlight\n    float rim = smoothstep(0.030, 0.0, abs(d)) * (1.0-body);\n    col += warm * rim * 0.25 * pane * flicker;\n\n    fragColor = vec4(col, 1.0);\n}\n"

SPRITE_FRAG = "uniform vec2  iResolution;\nuniform float iTime;\nuniform float uLocal;     // figure position across THIS window, 0..1\nuniform float uFacing;    // -1 left, +1 right\nuniform float uPhase;     // walk cycle 0..1 -> picks the atlas cell\nuniform float uLit;       // window glow level\nuniform float uFigScale;  // figure height as a fraction of the window\nuniform float uMirror;\nuniform float uFrames;    // frames in the atlas\nuniform float uCols;      // grid columns\nuniform float uRows;      // grid rows\nuniform float uCellAspect;// cell width / height\nuniform float uSrcFacing; // +1 if the source frames face RIGHT, -1 if LEFT\nuniform sampler2D uAtlas;\nout vec4 fragColor;\nvoid main(){\n    vec2 uv = gl_FragCoord.xy / iResolution;\n    float xs = (uMirror>0.5) ? -1.0 : 1.0;\n\n    // ---- lit window pane (same as the silhouette shader) ----\n    vec2 c = uv - 0.5;\n    float pane = smoothstep(0.52,0.40, abs(c.x)) * smoothstep(0.52,0.40, abs(c.y));\n    float falloff = 1.0 - 0.55*length(c*vec2(1.0,1.25));\n    float grime = 0.86 + 0.14*fbm(uv*vec2(6.0,8.0));\n    vec3 warm = vec3(1.00,0.72,0.34);\n    float flicker = uLit * (0.97 + 0.03*sin(iTime*3.1));\n    vec3 col = warm * pane * falloff * grime * flicker * 0.55;\n    col *= 0.92 + 0.08*sin(uv.x*38.0);\n\n    // ---- sample the figure out of the atlas ----\n    float screenAspect = iResolution.x / max(iResolution.y, 1.0);\n    float fh = max(0.05, uFigScale);              // height in uv\n    float fw = fh * uCellAspect / screenAspect;   // keep the cell's proportions\n    // position within the figure's quad, 0..1\n    vec2 q = vec2((uv.x - uLocal)/fw + 0.5, (uv.y - 0.045)/fh);\n    float body = 0.0;\n    if(q.x > 0.0 && q.x < 1.0 && q.y > 0.0 && q.y < 1.0){\n        vec2 f = q;\n        // flip only when the wanted direction differs from the source art\n        f.x = (uFacing*xs*uSrcFacing < 0.0) ? 1.0 - f.x : f.x;\n        float idx = floor(clamp(uPhase,0.0,0.9999) * uFrames);\n        float cx = mod(idx, uCols);\n        float cy = floor(idx / uCols);\n        // atlas rows run top-down; our uv is y-up\n        vec2 cell = vec2((cx + f.x)/uCols, (cy + (1.0 - f.y))/uRows);\n        body = texture(uAtlas, cell).a;\n    }\n\n    // contact shadow under the feet\n    float sh = smoothstep(0.16,0.0, length((uv - vec2(uLocal, 0.048))/vec2(0.085,0.028)));\n    col *= 1.0 - 0.45*sh*pane;\n    col *= 1.0 - 0.97*body;\n    fragColor = vec4(col, 1.0);\n}\n"

GHOST_FRAG = 'uniform vec2  iResolution;\nuniform float iTime;\nuniform float uLocal;     // x across THIS window, 0..1 (may be outside)\nuniform float uFacing;\nuniform float uPhase;\nuniform float uLit;\nuniform float uCrouch;\nuniform float uFigScale;\nuniform float uMirror;\nuniform float uDepth;     // 0 = right at the window .. 1 = far back in the room\nuniform float uYaw;       // radians, 0 = facing the viewer, +-pi/2 profile, pi = away\nout vec4 fragColor;\n// smooth union — blends primitives into one organic mass\nvoid main(){\n    vec2 uv = gl_FragCoord.xy / iResolution;\n    float xs = (uMirror>0.5) ? -1.0 : 1.0;\n    float aspect = iResolution.x / max(iResolution.y, 1.0);\n    float t = iTime;\n\n    // ---- depth: perspective scale, feet rise toward the horizon, fog, softness\n    float dz = clamp(uDepth, 0.0, 1.0);\n    float persp = 1.0 / (1.0 + dz*1.7);\n    float floorY = 0.09 + dz*0.24;\n    float fog = exp(-dz*1.35);\n    float soft = 0.045 + dz*0.07;\n    float lx = mix(uLocal, 0.5, dz*0.22);      // mild convergence to the window centre\n\n    // ---- yaw: foreshorten when in profile, face slides/fades as it turns\n    float cy = cos(uYaw), sy = sin(uYaw) * xs;\n    float wsq = mix(0.62, 1.0, abs(cy));\n    float faceVis = smoothstep(-0.10, 0.55, cy);\n    float faceShift = 0.075*sy;\n\n    float bob  = 0.028*sin(t*1.05 + uPhase*6.2831);\n    float sway = 0.010*sin(t*0.65 + uPhase*4.0);\n    float h = max(0.05, uFigScale) * persp;\n    vec2 p = vec2((uv.x - lx - sway) * aspect * xs, uv.y - floorY - bob) / h;\n    p.x /= wsq;\n\n    // veil ripple + slow large-scale billow of the whole form\n    p.x += 0.018*sin(p.y*8.0 - t*1.4) + 0.012*sin(p.y*3.0 + t*0.6);\n\n    // ---- body: hood, shoulders, robe, arms — all smooth-blended ----\n    vec2 hoodC = vec2(faceShift*0.6, 0.885);\n    float hood = length((p - hoodC)/vec2(0.90, 1.22)) - 0.108;\n    float neck = sdCap(p, vec2(faceShift*0.3,0.90), vec2(0.0,0.76), 0.092);\n    float shoulders = sdCap(p, vec2(-0.125,0.695), vec2(0.125,0.695), 0.070);\n    float robeA = sdCap(p, vec2(0.0,0.72), vec2(0.0,0.44), 0.140);\n    float robeB = sdCap(p, vec2(0.0,0.46), vec2(0.0,0.16), 0.185);\n    float body = smin(hood, neck, 0.07);\n    body = smin(body, shoulders, 0.11);\n    body = smin(body, robeA, 0.12);\n    body = smin(body, robeB, 0.16);\n\n    float armSw = 0.05*sin(t*0.9 + uPhase*6.2831);\n    float nearX = 0.135 + 0.03*sy, farX = 0.135 - 0.03*sy;\n    float armL = sdCap(p, vec2(-farX,0.68),  vec2(-farX-0.08, 0.40+armSw), 0.034);\n    armL = min(armL, sdCap(p, vec2(-farX-0.08,0.40+armSw), vec2(-farX-0.11,0.20+armSw), 0.025));\n    float armR = sdCap(p, vec2( nearX,0.68), vec2( nearX+0.085,0.42-armSw), 0.034);\n    armR = min(armR, sdCap(p, vec2(nearX+0.085,0.42-armSw), vec2(nearX+0.115,0.22-armSw), 0.025));\n    body = smin(body, min(armL, armR), 0.05);\n\n    // organic edge: ripple the distance field so no outline is a clean curve\n    body += (fbm(p*7.0 + vec2(0.0, -t*0.45)) - 0.5) * 0.055;\n\n    float shape = smoothstep(soft, -soft, body);\n\n    // ---- ragged hem and hanging strips ----\n    float hem = 0.20 + 0.16*fbm(vec2(p.x*4.5 - t*0.25, t*0.18))\n                     + 0.10*fbm(vec2(p.x*11.0 + t*0.4, 3.7));\n    shape *= smoothstep(hem - 0.14, hem + 0.20, p.y);\n    float strips = fbm(vec2(p.x*14.0 + sin(p.y*7.0 + t*0.9)*0.5, p.y*3.0 - t*0.9));\n    float below = smoothstep(hem + 0.04, hem - 0.26, p.y);\n    float strip = smoothstep(0.54, 0.80, strips) * below\n                * smoothstep(0.26, 0.06, abs(p.x)) * smoothstep(-0.22, 0.02, p.y);\n    shape = clamp(max(shape, strip*0.75), 0.0, 1.0);\n\n    // ---- vapour: layered, rising — a moving gas, not a cutout ----\n    float v1 = fbm(vec2(p.x*4.5, p.y*4.5 - t*0.55));\n    float v2 = fbm(vec2(p.x*9.0 + t*0.2, p.y*7.0 - t*0.9) + 4.0);\n    float density = 0.42 + 0.65*v1 + 0.25*v2;\n\n    // ---- colour ----\n    vec3 core = vec3(0.86,0.96,1.00);\n    vec3 edge = vec3(0.22,0.50,0.82);\n    float edgeness = smoothstep(-0.17, 0.02, body);\n    vec3 col = mix(core, edge, edgeness);\n    col += vec3(0.35,0.55,0.75) * exp(-length((p - vec2(0.0,0.55))/vec2(0.7,1.0))*4.5) * 0.6;\n    col += vec3(0.55,0.80,1.0) * smoothstep(0.06, 0.0, abs(body)) * 0.85;\n\n    // ---- hollow face (fades as it turns away, slides toward the turn) ----\n    vec2 e1 = vec2(-0.046 + faceShift, 0.905), e2 = vec2(0.046 + faceShift, 0.905);\n    float sock = min(length((p-e1)/vec2(1.0,2.1)), length((p-e2)/vec2(1.0,2.1)));\n    float hollow = smoothstep(0.085, 0.030, sock) * faceVis;\n    col *= 1.0 - 0.96*hollow;\n    float spark = smoothstep(0.022, 0.004, min(length(p-e1-vec2(0.0,-0.012)),\n                                               length(p-e2-vec2(0.0,-0.012)))) * faceVis;\n    col += vec3(0.45,0.78,1.0) * spark * 0.9;\n    col *= 1.0 - 0.45*faceVis*smoothstep(0.075,0.015, length((p - vec2(faceShift,0.965))/vec2(0.55,1.0)));\n    float mth = length((p - vec2(faceShift*0.8,0.800))/vec2(1.0, 2.6));\n    col *= 1.0 - 0.88*faceVis*smoothstep(0.070, 0.022, mth);\n    col *= mix(0.78, 1.0, faceVis);\n\n    // depth fog: dim and blue-shift EXISTING light only\n    float a = clamp(shape * density, 0.0, 1.0) * uLit;\n    float aura = exp(-pow(length(p - vec2(0.0,0.62))*1.5, 2.0)) * 0.22;\n    vec3 outc = col * a + vec3(0.20,0.42,0.75) * aura * uLit;\n    float lum = dot(outc, vec3(0.333));\n    outc = outc*fog + vec3(0.10,0.22,0.45)*lum*(1.0-fog)*0.8;\n    fragColor = vec4(outc, 1.0);\n}\n'

MANSION_FRAG = "uniform vec2  iResolution;\nuniform float iTime;\nuniform float uFigScale;\nuniform float uMirror;\nuniform float uPos[SLOTS];     // x across THIS window per dancer (may be outside)\nuniform float uDepth[SLOTS];\nuniform float uYaw[SLOTS];\nuniform float uPhase[SLOTS];\nuniform float uLit[SLOTS];     // materialize / dematerialize\nout vec4 fragColor;\n// ---- a sculpted, grinning face. q is head-local (unit radius). ----\n// kind 0 = gentleman (mustache, wide toothy grin), 1 = lady (lashes, lips).\n// sy = yaw sine: features slide/ compress as the head turns.\nvec2 face(vec2 q, float kind, float sy){\n    float dark = 0.0, light = 0.0;\n    q.x -= 0.10*sy;                         // features slide toward the turn\n    q.x /= mix(0.6, 1.0, 1.0 - abs(sy)*0.6); // and compress in profile\n\n    // brow ridge: a shadow band across the forehead, then arched brows\n    dark += 0.18*smoothstep(0.62,0.40, q.y)*smoothstep(0.20,0.40,q.y);\n    float bt = 0.36 + 0.06*kind;   // the lady's brows sit a little higher and flatter\n    float browL = sdCap(q, vec2(-0.66,0.44), vec2(-0.16,bt), 0.075 - 0.02*kind);\n    float browR = sdCap(q, vec2( 0.16,bt), vec2( 0.66,0.44), 0.075 - 0.02*kind);\n    dark += 0.55*smoothstep(0.02,-0.03, min(browL,browR));\n\n    // deep eye sockets, with the eyeball catching light inside\n    vec2 sL = vec2(-0.37, 0.12), sR = vec2(0.37, 0.12);\n    float sockL = length((q-sL)/vec2(0.27,0.22)), sockR = length((q-sR)/vec2(0.27,0.22));\n    float sock = min(sockL, sockR);\n    dark += 0.80*smoothstep(1.0, 0.55, sock);                 // hollow\n    float eyeL = length((q-sL-vec2(0.02,-0.02))/vec2(0.16,0.13));\n    float eyeR = length((q-sR-vec2(0.02,-0.02))/vec2(0.16,0.13));\n    light += 0.55*smoothstep(1.0, 0.6, min(eyeL,eyeR));       // the eyeball\n    float pupL = length(q-sL-vec2(0.05,-0.03)), pupR = length(q-sR-vec2(0.05,-0.03));\n    dark += 0.9*smoothstep(0.075,0.045, min(pupL,pupR));      // pupil\n    light += 0.9*smoothstep(0.03,0.0, min(length(q-sL-vec2(0.09,0.01)),\n                                          length(q-sR-vec2(0.09,0.01)))); // glint\n    // lashes / heavy upper lid on the lady\n    dark += kind*0.45*smoothstep(0.03,-0.02, min(sdCap(q, sL+vec2(-0.26,0.16), sL+vec2(0.24,0.20), 0.03),\n                                                 sdCap(q, sR+vec2(-0.24,0.20), sR+vec2(0.26,0.16), 0.03)));\n\n    // nose: a shadow down one side of the ridge and under the tip\n    float ridge = sdCap(q, vec2(0.0,0.12), vec2(0.04,-0.16), 0.05);\n    dark += 0.30*smoothstep(0.06,-0.02, ridge) * smoothstep(-0.05,0.10, q.x - 0.02);\n    dark += 0.35*smoothstep(0.12,0.02, length((q-vec2(0.05,-0.24))/vec2(0.16,0.09)));\n    light += 0.25*smoothstep(0.05,0.0, sdCap(q, vec2(-0.03,0.10), vec2(-0.01,-0.12), 0.02));\n\n    // cheekbones: shading under them, a highlight on top\n    dark += 0.22*smoothstep(1.0,0.5, min(length((q-vec2(-0.55,-0.30))/vec2(0.30,0.24)),\n                                         length((q-vec2( 0.55,-0.30))/vec2(0.30,0.24))));\n    light += 0.18*smoothstep(1.0,0.5, min(length((q-vec2(-0.50,-0.12))/vec2(0.22,0.10)),\n                                          length((q-vec2( 0.50,-0.12))/vec2(0.22,0.10))));\n\n    // the grin: a wide upturned mouth\n    vec2 mc = vec2(0.0, -0.40);\n    float mouthOuter = length((q-mc)/vec2(0.60,0.26));\n    float upperLip = smoothstep(-0.30, -0.36, q.y);            // only the lower half\n    float grinMask = smoothstep(1.0,0.85, mouthOuter) * upperLip;\n    dark += 0.90*grinMask;\n    // corners turn up into the cheeks\n    dark += 0.6*smoothstep(0.05,-0.01, min(sdCap(q, vec2(-0.55,-0.38), vec2(-0.66,-0.26), 0.04),\n                                           sdCap(q, vec2( 0.55,-0.38), vec2( 0.66,-0.26), 0.04)));\n    // teeth: a lit band inside the grin with dark gaps\n    float teethBand = smoothstep(-0.36,-0.40,q.y)*smoothstep(-0.56,-0.50,q.y)*smoothstep(1.0,0.8,mouthOuter);\n    float gaps = smoothstep(0.06,0.12, abs(fract(q.x*6.0 + 0.5)-0.5));\n    light += (0.75 - 0.55*kind) * teethBand * gaps;\n    // a dark line for the lady's parted lips instead of a full toothy grin\n    dark += kind*0.5*smoothstep(0.03,0.0, abs(q.y + 0.40 - 0.10*abs(q.x)))*smoothstep(0.55,0.35,abs(q.x));\n\n    // the gentleman's mustache: curling up at the ends\n    float mst = min(sdCap(q, vec2(0.0,-0.26), vec2(-0.42,-0.20), 0.07),\n                    sdCap(q, vec2(0.0,-0.26), vec2( 0.42,-0.20), 0.07));\n    mst = min(mst, min(sdCap(q, vec2(-0.42,-0.20), vec2(-0.52,-0.06), 0.045),\n                       sdCap(q, vec2( 0.42,-0.20), vec2( 0.52,-0.06), 0.045)));\n    dark += (1.0-kind)*0.85*smoothstep(0.03,-0.03, mst);\n\n    // chin shadow\n    dark += 0.20*smoothstep(0.30,0.05, length((q-vec2(0.0,-0.68))/vec2(0.45,0.22)));\n    return vec2(clamp(dark,0.0,1.0), clamp(light,0.0,1.0));\n}\n\n// ---- a gentleman: top hat, tailcoat, cane ----\nfloat gent(vec2 p, float sy, float t, float ph){\n    float head = length((p - vec2(0.0,0.865))/vec2(1.0,1.08)) - 0.078;\n    head = smin(head, length(p - vec2(0.005,0.80)) - 0.058, 0.035);\n    // top hat\n    float brim = sdCap(p, vec2(-0.105,0.935), vec2(0.105,0.935), 0.012);\n    float crown = sdBox(p - vec2(0.0,1.02), vec2(0.066,0.085));\n    float hat = min(brim, crown);\n    // collar + torso + shoulders\n    float torso = sdCap(p, vec2(0.0,0.78), vec2(0.0,0.50), 0.095);\n    float shoulders = sdCap(p, vec2(-0.125,0.755), vec2(0.125,0.755), 0.055);\n    float d = smin(head, torso, 0.05);\n    d = smin(d, shoulders, 0.06);\n    d = min(d, hat);\n    // coat tails flaring behind\n    float tails = sdCap(p, vec2(-0.06*sy,0.50), vec2(-0.14*sy,0.22), 0.050);\n    d = smin(d, tails, 0.08);\n    // lower body narrowing into ectoplasm (no legs)\n    float lower = sdCap(p, vec2(0.0,0.52), vec2(0.0,0.16), 0.075);\n    d = smin(d, lower, 0.10);\n    // arms: one hand on the cane, one raised in a flourish\n    float sw = 0.03*sin(ph*6.2831);\n    float armC = sdCap(p, vec2(0.11,0.74), vec2(0.15,0.47), 0.030);\n    float cane = sdCap(p, vec2(0.15,0.47), vec2(0.18,0.05), 0.008);\n    float armF = sdCap(p, vec2(-0.11,0.74), vec2(-0.22,0.62+sw), 0.030);\n    armF = min(armF, sdCap(p, vec2(-0.22,0.62+sw), vec2(-0.20,0.80+sw), 0.026));\n    d = smin(d, min(armC, armF), 0.04);\n    d = min(d, cane);\n    return d;\n}\n\n// ---- a lady: bonnet, bodice, bell gown ----\nfloat lady(vec2 p, float sy, float t, float ph){\n    float head = length((p - vec2(0.0,0.855))/vec2(1.0,1.08)) - 0.073;\n    head = smin(head, length(p - vec2(0.0,0.795)) - 0.050, 0.035);\n    // bonnet / hair piled up, tilted slightly back\n    float bonnet = length((p - vec2(-0.02*sy,0.915))/vec2(1.15,0.95)) - 0.085;\n    bonnet = max(bonnet, -(length(p - vec2(0.02*sy,0.84)) - 0.085)); // open at the face\n    float torso = sdCap(p, vec2(0.0,0.77), vec2(0.0,0.56), 0.070);\n    float shoulders = sdCap(p, vec2(-0.105,0.745), vec2(0.105,0.745), 0.045);\n    // gown: a bell that widens toward the hem\n    float yy = clamp((p.y - 0.10)/0.48, 0.0, 1.0);\n    float hw = mix(0.30, 0.085, pow(yy, 0.6));\n    float gown = abs(p.x) - hw;\n    gown = max(gown, 0.10 - p.y);\n    gown = max(gown, p.y - 0.60);\n    // soften the gown edges\n    gown = gown - 0.02;\n    float d = smin(head, torso, 0.04);\n    d = smin(d, shoulders, 0.05);\n    d = smin(d, gown, 0.06);\n    d = min(d, bonnet);\n    // arms: one raised to a partner, one lifting the skirt\n    float sw = 0.03*sin(ph*6.2831);\n    float armU = sdCap(p, vec2(0.10,0.74), vec2(0.21,0.84+sw), 0.026);\n    float armD = sdCap(p, vec2(-0.10,0.74), vec2(-0.20,0.52-sw), 0.026);\n    d = smin(d, min(armU, armD), 0.035);\n    return d;\n}\n\nvoid main(){\n    vec2 uv = gl_FragCoord.xy / iResolution;\n    float xs = (uMirror>0.5) ? -1.0 : 1.0;\n    float aspect = iResolution.x / max(iResolution.y, 1.0);\n    float t = iTime;\n    vec3 col = vec3(0.0);\n\n    // Pepper's-Ghost green-white palette\n    vec3 core = vec3(0.80,1.00,0.86);\n    vec3 edge = vec3(0.18,0.70,0.48);\n\n    for(int i=0;i<SLOTS;i++){\n        float lit = uLit[i];\n        if(lit < 0.01) continue;\n        float dz = clamp(uDepth[i], 0.0, 1.0);\n        float persp = 1.0/(1.0 + dz*1.7);\n        float floorY = 0.09 + dz*0.24;\n        float fog = exp(-dz*1.1);\n        float soft = 0.030 + dz*0.05;\n        float lx = mix(uPos[i], 0.5, dz*0.22);\n        float yaw = uYaw[i];\n        float cy = cos(yaw), sy = sin(yaw)*xs;\n        float wsq = mix(0.55, 1.0, abs(cy));\n        float faceVis = smoothstep(-0.10, 0.55, cy);\n        float ph = uPhase[i];\n        // the waltz: a lilting rise and fall\n        float bob = 0.030*sin(ph*6.2831) + 0.012*sin(ph*12.566);\n        float h = max(0.05, uFigScale) * persp;\n        vec2 p = vec2((uv.x - lx)*aspect*xs, uv.y - floorY - bob) / h;\n        p.x /= wsq;\n        if(abs(p.x) > 0.75 || p.y < -0.45 || p.y > 1.30) continue;\n\n        // gentle drift of the whole form\n        p.x += 0.010*sin(p.y*6.0 - t*1.2);\n\n        float kind = float(i - 2*(i/2));   // 0 gent, 1 lady, 0 gent\n        float body = (kind < 0.5) ? gent(p, sy, t, ph) : lady(p, sy, t, ph);\n        body += (fbm4(p*6.0 + vec2(0.0,-t*0.4) + float(i)*7.0) - 0.5) * 0.030;\n        float shape = smoothstep(soft, -soft, body);\n\n        // ectoplasm: the figure dissolves upward from below into drifting wisps\n        float ect = fbm4(vec2(p.x*7.0 + sin(p.y*5.0 + t)*0.4, p.y*3.0 - t*0.8) + float(i)*3.0);\n        float hemY = 0.16 + 0.10*fbm4(vec2(p.x*4.0 - t*0.2, float(i)));\n        shape *= smoothstep(hemY - 0.14, hemY + 0.16, p.y);\n        float wisp = smoothstep(0.55,0.82, ect) * smoothstep(hemY+0.06, hemY-0.25, p.y)\n                   * smoothstep(0.30,0.08,abs(p.x)) * smoothstep(-0.30,0.0,p.y);\n        shape = clamp(max(shape, wisp*0.7), 0.0, 1.0);\n\n        // materialize: reveal through noise as lit rises\n        float grain = fbm4(p*5.0 + float(i)*11.0 + vec2(0.0, t*0.15));\n        float reveal = smoothstep(-0.08, 0.20, lit - grain*0.9);\n        shape *= reveal;\n\n        // translucency: layered vapour density; see-through in places\n        float v1 = fbm4(vec2(p.x*4.0, p.y*4.0 - t*0.5) + float(i)*5.0);\n        float v2 = fbm4(vec2(p.x*8.0 + t*0.2, p.y*6.0 - t*0.8) + float(i)*9.0);\n        float density = 0.40 + 0.55*v1 + 0.30*v2;\n\n        float edgeness = smoothstep(-0.15, 0.02, body);\n        vec3 c = mix(core, edge, edgeness);\n        // spectral rim\n        c += vec3(0.55,1.0,0.80) * smoothstep(0.05, 0.0, abs(body)) * 0.8;\n        // faint inner glow at the chest\n        c += vec3(0.30,0.55,0.40) * exp(-length((p - vec2(0.0,0.62))/vec2(0.6,1.0))*5.0) * 0.5;\n\n        // ---- the face: sculpted and grinning, only on the head ----\n        float headY = (kind < 0.5) ? 0.865 : 0.855;\n        float headR = (kind < 0.5) ? 0.078 : 0.073;\n        vec2 q = (p - vec2(0.0, headY)) / headR;\n        float onHead = smoothstep(1.35, 1.05, length(q));\n        vec2 fx = face(q, kind, sy) * faceVis * onHead;\n        c *= 1.0 - fx.x;\n        c += vec3(0.75,1.0,0.85) * fx.y;\n\n        // projection shimmer: faint horizontal bands drifting, like light through glass\n        c *= 0.975 + 0.025*sin(uv.y*260.0 + t*6.0 + float(i));\n\n        float a = clamp(shape*density, 0.0, 1.0) * lit;\n        c *= fog;\n        col = mix(col, c, a*0.92);          // over-composite (far dancers sent first)\n        // soft aura, faded to nothing well inside the evaluation box so no edge shows\n        float win = smoothstep(0.75,0.40,abs(p.x)) * smoothstep(-0.45,-0.05,p.y) * smoothstep(1.30,0.95,p.y);\n        col += vec3(0.25,0.60,0.45) * exp(-pow(length(p - vec2(0.0,0.62))*1.6,2.0)) * 0.16 * lit * fog * win;\n    }\n    fragColor = vec4(col, 1.0);\n}\n"

SPIRITS_FRAG = "uniform vec2  iResolution;\nuniform float iTime;\nuniform float uFigScale;\nuniform float uMirror;\nuniform float uX[SLOTS];\nuniform float uY[SLOTS];\nuniform float uZ[SLOTS];\nuniform float uLit[SLOTS];\n// past positions, flattened [spirit*NH + point]; point 0 = oldest, NH-1 = newest\nuniform float uHX[SLOTS*NH];\nuniform float uHY[SLOTS*NH];\nuniform float uHZ[SLOTS*NH];\nout vec4 fragColor;\n// project a room position (x along the stage, y height, z depth) to screen uv\nvec2 proj(vec3 r, float xs){\n    float persp = 1.0/(1.0 + r.z*1.7);\n    float sx = mix(r.x, 0.5, r.z*0.22);\n    float sy = 0.10 + r.z*0.24 + r.y*0.72*persp;\n    sx = 0.5 + (sx-0.5)*xs;\n    return vec2(sx, sy);\n}\n\nvoid main(){\n    vec2 uv = gl_FragCoord.xy / iResolution;\n    float xs = (uMirror>0.5) ? -1.0 : 1.0;\n    float aspect = iResolution.x / max(iResolution.y, 1.0);\n    float t = iTime;\n    vec3 col = vec3(0.0);\n\n    // three cold palettes: pale blue, dead white, sick green; slot picks one\n    vec3 pal[3];\n    pal[0] = vec3(0.45,0.70,1.00);\n    pal[1] = vec3(0.90,0.95,1.00);\n    pal[2] = vec3(0.35,0.95,0.55);\n\n    for(int i=0;i<SLOTS;i++){\n        float lit = uLit[i];\n        if(lit < 0.01) continue;\n        vec3 r = vec3(uX[i], uY[i], uZ[i]);\n        float persp = 1.0/(1.0 + r.z*1.7);\n        float fog = exp(-r.z*1.15);\n        vec2 c = proj(r, xs);\n        float kind = float(i - 2*(i/2));     // 0 = orb, 1 = wisp\n        float size = max(0.02, uFigScale) * 0.16 * persp;\n        vec3 tint = pal[i - 3*(i/3)];\n        vec2 p = (uv - c) * vec2(aspect,1.0) / size;\n\n        // ---- trail: walk the spirit's ACTUAL past positions, so it bends\n        //      through every curve it flew instead of shooting off straight.\n        float trail = 0.0;\n        float spd = 0.0;\n        vec2 prev = vec2(0.0);\n        bool havePrev = false;\n        for(int k=0;k<NH;k++){\n            int idx = i*NH + k;\n            vec3 hp = vec3(uHX[idx], uHY[idx], uHZ[idx]);\n            vec2 sp = (proj(hp, xs) - c) * vec2(aspect,1.0) / size;\n            if(havePrev){\n                float age = float(k) / float(NH-1);        // 0 oldest .. 1 newest\n                float h;\n                float ds = sdSeg(p, prev, sp, h);\n                // thickness and brightness taper toward the tail\n                float w = mix(0.06, 0.40, age);     // thin, so the curve stays legible\n                float br = mix(0.0, 1.0, age);\n                float wob = 0.55 + 0.45*fbm4(vec2(age*7.0 - t*3.0, float(i)*3.0));\n                trail += exp(-ds*ds/(w*w)) * br * br * wob;\n                spd += length(sp - prev);\n            }\n            prev = sp; havePrev = true;\n        }\n        trail = min(trail, 1.8);\n        if(length(p) > 6.0 + spd) continue;\n\n        float a = 0.0;\n        if(kind < 0.5){\n            // ---- ORB: a burning core, a soft halo, a trail that thins behind\n            float d = length(p);\n            float core = exp(-d*d*9.0);\n            float halo = exp(-d*1.6) * 0.35;\n            // breathing pulse\n            core *= 0.85 + 0.15*sin(t*4.0 + float(i)*2.0);\n            a = core*1.2 + halo + trail*0.85;\n            col += tint * a * lit * fog;\n            col += vec3(1.0) * core * 0.5 * lit * fog;      // white-hot centre\n        } else {\n            // ---- WISP: no hard centre — a writhing knot of smoke drawn out behind\n            vec2 wq = p + vec2(fbm4(p*1.3 + t*0.5 + float(i)) - 0.5, fbm4(p*1.3 - t*0.4) - 0.5)*1.4;\n            float body = fbm4(wq*1.1 + vec2(t*0.6, -t*0.3));\n            float env = exp(-length(p)*1.35) * 1.2 + trail*0.75;\n            a = smoothstep(0.22, 0.72, body) * env * 2.2;\n            // dark veins through the smoke, so it isn't a flat cloud\n            a *= 0.55 + 0.45*smoothstep(0.35, 0.6, fbm4(wq*3.0 - t*0.8));\n            // a faint hot knot at its heart so it reads as an entity, not weather\n            a += exp(-length(p)*length(p)*2.5) * 0.35 * (0.8+0.2*sin(t*3.0+float(i)));\n            col += tint * a * lit * fog;\n        }\n    }\n    fragColor = vec4(col, 1.0);\n}\n"

STAGE_SHADERS = {"silhouette": SILHOUETTE_FRAG, "sprite": SPRITE_FRAG, "ghost": GHOST_FRAG, "mansion": MANSION_FRAG, "spirits": SPIRITS_FRAG}
